     1	<!DOCTYPE html>
     2	<html lang="en">
     3	<head>
     4	<meta charset="utf-8">
     5	<meta name="viewport" content="width=device-width, initial-scale=1">
     6	<title>Tetris</title>
     7	<style>
     8	  :root {
     9	    --cell: 28px;
    10	    --bg: #14161c;
    11	    --panel: #1d2029;
    12	    --grid: #262a35;
    13	    --text: #e8eaf0;
    14	    --muted: #8a90a0;
    15	  }
    16	  * { box-sizing: border-box; }
    17	  body {
    18	    margin: 0;
    19	    min-height: 100vh;
    20	    display: flex;
    21	    align-items: center;
    22	    justify-content: center;
    23	    background: var(--bg);
    24	    color: var(--text);
    25	    font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    26	  }
    27	  .game {
    28	    display: flex;
    29	    gap: 20px;
    30	    align-items: flex-start;
    31	    padding: 16px;
    32	  }
    33	  .board {
    34	    display: grid;
    35	    grid-template-columns: repeat(10, var(--cell));
    36	    grid-template-rows: repeat(20, var(--cell));
    37	    gap: 1px;
    38	    padding: 1px;
    39	    background: var(--grid);
    40	    border: 2px solid #3a3f4d;
    41	    border-radius: 4px;
    42	    position: relative;
    43	  }
    44	  .cell { background: var(--bg); }
    45	  .side {
    46	    display: flex;
    47	    flex-direction: column;
    48	    gap: 12px;
    49	    min-width: 140px;
    50	  }
    51	  .box {
    52	    background: var(--panel);
    53	    border-radius: 6px;
    54	    padding: 10px 12px;
    55	  }
    56	  .label {
    57	    font-size: 11px;
    58	    text-transform: uppercase;
    59	    letter-spacing: 0.08em;
    60	    color: var(--muted);
    61	  }
    62	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
    63	  .preview {
    64	    display: flex;
    65	    flex-direction: column;
    66	    gap: 10px;
    67	    margin-top: 8px;
    68	  }
    69	  .preview-item {
    70	    display: grid;
    71	    grid-template-columns: repeat(4, 16px);
    72	    grid-template-rows: repeat(2, 16px);
    73	    gap: 1px;
    74	  }
    75	  .hold-used .preview-item { opacity: 0.35; }
    76	  .help { color: var(--muted); font-size: 12px; }
    77	  .help kbd {
    78	    background: #2b2f3a;
    79	    border-radius: 3px;
    80	    padding: 0 4px;
    81	    font: inherit;
    82	    color: var(--text);
    83	  }
    84	  .overlay {
    85	    position: absolute;
    86	    inset: 0;
    87	    display: flex;
    88	    flex-direction: column;
    89	    align-items: center;
    90	    justify-content: center;
    91	    gap: 10px;
    92	    background: rgba(10, 11, 15, 0.78);
    93	    font-size: 20px;
    94	    font-weight: 600;
    95	  }
    96	  .overlay button {
    97	    font: inherit;
    98	    font-size: 14px;
    99	    padding: 6px 14px;
   100	    border: 0;
   101	    border-radius: 4px;
   102	    background: #4a8cff;
   103	    color: #fff;
   104	    cursor: pointer;
   105	  }
   106	  .overlay[hidden] { display: none; }
   107	  .pause-btn {
   108	    width: 100%;
   109	    font: inherit;
   110	    padding: 6px 10px;
   111	    border: 0;
   112	    border-radius: 4px;
   113	    background: #2b2f3a;
   114	    color: var(--text);
   115	    cursor: pointer;
   116	  }
   117	  .pause-btn:hover { background: #353a47; }
   118	
   119	  /* Piece colours */
   120	  .p-I { background: #30c7e6; }
   121	  .p-O { background: #f2d33a; }
   122	  .p-T { background: #a35ee0; }
   123	  .p-S { background: #4ccf5a; }
   124	  .p-Z { background: #e8474a; }
   125	  .p-J { background: #3b6ee8; }
   126	  .p-L { background: #f09a2e; }
   127	
   128	  /* Ghost outlines */
   129	  .g-I { box-shadow: inset 0 0 0 2px #30c7e6; }
   130	  .g-O { box-shadow: inset 0 0 0 2px #f2d33a; }
   131	  .g-T { box-shadow: inset 0 0 0 2px #a35ee0; }
   132	  .g-S { box-shadow: inset 0 0 0 2px #4ccf5a; }
   133	  .g-Z { box-shadow: inset 0 0 0 2px #e8474a; }
   134	  .g-J { box-shadow: inset 0 0 0 2px #3b6ee8; }
   135	  .g-L { box-shadow: inset 0 0 0 2px #f09a2e; }
   136	</style>
   137	</head>
   138	<body>
   139	<div class="game">
   140	  <div class="board" data-testid="board" id="board">
   141	    <div class="overlay" data-testid="game-over" id="overlay" hidden>
   142	      <div>Game over</div>
   143	      <button type="button" id="restart">Play again</button>
   144	    </div>
   145	    <div class="overlay" data-testid="paused-indicator" id="paused" hidden>
   146	      <div>Paused</div>
   147	    </div>
   148	  </div>
   149	  <div class="side">
   150	    <div class="box">
   151	      <div class="label">Score</div>
   152	      <div class="value" data-testid="score" id="score">0</div>
   153	    </div>
   154	    <div class="box">
   155	      <div class="label">Level</div>
   156	      <div class="value" data-testid="level" id="level">1</div>
   157	    </div>
   158	    <div class="box">
   159	      <div class="label">Lines</div>
   160	      <div class="value" data-testid="lines" id="lines">0</div>
   161	    </div>
   162	    <div class="box" id="hold-box">
   163	      <div class="label">Hold</div>
   164	      <div class="preview">
   165	        <div class="preview-item" data-testid="hold-piece" id="hold" data-piece=""></div>
   166	      </div>
   167	    </div>
   168	    <div class="box">
   169	      <div class="label">Next</div>
   170	      <div class="preview" data-testid="next-piece" id="preview"></div>
   171	    </div>
   172	    <button type="button" class="pause-btn" data-testid="pause-btn" id="pause-btn" aria-pressed="false">Pause</button>
   173	    <div class="box help">
   174	      <div><kbd>←</kbd> <kbd>→</kbd> Move</div>
   175	      <div><kbd>↑</kbd> <kbd>X</kbd> Rotate</div>
   176	      <div><kbd>↓</kbd> Soft drop</div>
   177	      <div><kbd>Space</kbd> Hard drop</div>
   178	      <div><kbd>C</kbd> <kbd>Shift</kbd> Hold</div>
   179	      <div><kbd>P</kbd> <kbd>Esc</kbd> Pause</div>
   180	    </div>
   181	  </div>
   182	</div>
   183	
   184	<script>
   185	(function () {
   186	  "use strict";
   187	
   188	  var ROWS = 20;
   189	  var COLS = 10;
   190	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
   191	
   192	  // Spawn shapes as [row, col] offsets. Top row of every shape is row 0.
   193	  var SHAPES = {
   194	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
   195	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
   196	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
   197	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
   198	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
   199	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
   200	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
   201	  };
   202	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
   203	
   204	  // The I piece has its own rotation states so it turns in place like the
   205	  // guideline piece, without ever reaching above the piece's own row.
   206	  var I_STATES = [
   207	    [[0, 0], [0, 1], [0, 2], [0, 3]],
   208	    [[0, 2], [1, 2], [2, 2], [3, 2]],
   209	    [[1, 0], [1, 1], [1, 2], [1, 3]],
   210	    [[0, 1], [1, 1], [2, 1], [3, 1]]
   211	  ];
   212	  // Sideways shifts tried, in order, when a rotated shape does not fit.
   213	  var KICKS = [0, -1, 1, -2, 2];
   214	
   215	  // Locking rule.
   216	  var LOCK_DELAY = 2;      // gravity ticks a piece may spend unable to fall
   217	  var MAX_LOCK_RESETS = 3; // times a piece may restart its lock delay
   218	
   219	  // Scoring rule. Points for a clear depend on how many rows go at once, times
   220	  // the current level. The table grows faster than the row count, so clearing
   221	  // rows together always beats clearing the same rows one at a time.
   222	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
   223	  var SOFT_DROP_POINTS = 1; // per cell moved down by the player
   224	  var HARD_DROP_POINTS = 2; // per cell dropped
   225	
   226	  // Levelling rule. One level per LINES_PER_LEVEL lines cleared, never down.
   227	  var LINES_PER_LEVEL = 10;
   228	
   229	  // ---- State ----
   230	  var board;       // ROWS x COLS array of piece letters or null
   231	  var current;     // { type, row, col, rot, shape, lockTicks, lockResets } or null
   232	  var queue;       // upcoming piece letters, soonest first
   233	  var bag;         // 7-bag for the random generator
   234	  var hold;        // letter of the held piece, or null
   235	  var canHold;     // false once the falling piece has used its hold
   236	  var score, level, lines, status; // status: "running", "paused" or "gameover"
   237	  var timer = null;        // pending gravity timeout, or null when stopped
   238	  var tickDue = 0;         // Date.now() at which the pending gravity step fires
   239	  var pausedRemaining = 0; // ms left until the next gravity step, kept over a pause
   240	
   241	  function emptyBoard() {
   242	    var b = [];
   243	    for (var r = 0; r < ROWS; r++) {
   244	      var row = [];
   245	      for (var c = 0; c < COLS; c++) row.push(null);
   246	      b.push(row);
   247	    }
   248	    return b;
   249	  }
   250	
   251	  function randomPiece() {
   252	    if (!bag || bag.length === 0) {
   253	      bag = TYPES.slice();
   254	      for (var i = bag.length - 1; i > 0; i--) {
   255	        var j = Math.floor(Math.random() * (i + 1));
   256	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
   257	      }
   258	    }
   259	    return bag.pop();
   260	  }
   261	
   262	  function sanitizeQueue(q) {
   263	    if (!Array.isArray(q)) return [];
   264	    return q.map(function (x) { return String(x).toUpperCase(); })
   265	            .filter(function (x) { return TYPES.indexOf(x) !== -1; });
   266	  }
   267	
   268	  // Keep at least the next piece queued for the preview.
   269	  var PREVIEW_COUNT = 1;
   270	  function fillQueue() {
   271	    while (queue.length < PREVIEW_COUNT) queue.push(randomPiece());
   272	  }
   273	
   274	  function pieceCells(p, dRow, dCol) {
   275	    var out = [];
   276	    for (var i = 0; i < p.shape.length; i++) {
   277	      out.push([p.row + p.shape[i][0] + (dRow || 0), p.col + p.shape[i][1] + (dCol || 0)]);
   278	    }
   279	    return out;
   280	  }
   281	
   282	  function fits(p, dRow, dCol) {
   283	    var cells = pieceCells(p, dRow, dCol);
   284	    for (var i = 0; i < cells.length; i++) {
   285	      var r = cells[i][0], c = cells[i][1];
   286	      if (c < 0 || c >= COLS || r >= ROWS) return false;
   287	      if (r >= 0 && board[r][c]) return false;
   288	    }
   289	    return true;
   290	  }
   291	
   292	  function spawn() {
   293	    fillQueue();
   294	    var type = queue.shift();
   295	    fillQueue();
   296	    enter(type);
   297	  }
   298	
   299	  // Put a piece of the given type at the spawn position, or end the game if
   300	  // it does not fit there.
   301	  function enter(type) {
   302	    var p = {
   303	      type: type, row: 0, col: SPAWN_COL[type], rot: 0, shape: SHAPES[type],
   304	      lockTicks: 0, lockResets: 0
   305	    };
   306	    if (!fits(p, 0, 0)) {
   307	      current = null;
   308	      status = "gameover";
   309	      stopTimer();
   310	      return;
   311	    }
   312	    current = p;
   313	  }
   314	
   315	  function lock() {
   316	    var cells = pieceCells(current, 0, 0);
   317	    for (var i = 0; i < cells.length; i++) {
   318	      var r = cells[i][0], c = cells[i][1];
   319	      if (r >= 0 && r < ROWS && c >= 0 && c < COLS) board[r][c] = current.type;
   320	    }
   321	    current = null;
   322	    canHold = true;
   323	    clearLines();
   324	    spawn();
   325	  }
   326	
   327	  // Remove every full row; everything above drops down to fill the gap.
   328	  function clearLines() {
   329	    var kept = board.filter(function (row) {
   330	      return row.some(function (v) { return !v; });
   331	    });
   332	    var cleared = ROWS - kept.length;
   333	    if (cleared === 0) return;
   334	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
   335	    board = kept;
   336	    score += CLEAR_POINTS[cleared] * level;
   337	    // Each multiple of LINES_PER_LEVEL crossed adds one level, counting on
   338	    // from whatever the level is now (setLevel may have moved it).
   339	    var gained = Math.floor((lines + cleared) / LINES_PER_LEVEL) - Math.floor(lines / LINES_PER_LEVEL);
   340	    lines += cleared;
   341	    if (gained > 0) {
   342	      level += gained;
   343	      if (timer !== null) startTimer();
   344	    }
   345	  }
   346	
   347	  // One gravity step. The real timer, tick() and a falling soft drop run this.
   348	  // If the piece cannot fall, the step counts one tick of lock delay instead.
   349	  // Returns true if the piece moved down.
   350	  function gravityStep() {
   351	    if (status !== "running" || !current) return false;
   352	    if (fits(current, 1, 0)) {
   353	      current.row += 1;
   354	      current.lockTicks = 0;
   355	      return true;
   356	    }
   357	    current.lockTicks += 1;
   358	    if (current.lockTicks >= LOCK_DELAY) lock();
   359	    return false;
   360	  }
   361	
   362	  // Player input on a resting piece restarts the lock delay, up to
   363	  // MAX_LOCK_RESETS times per piece.
   364	  function restartLockDelay() {
   365	    if (current.lockResets < MAX_LOCK_RESETS) {
   366	      current.lockResets += 1;
   367	      current.lockTicks = 0;
   368	    }
   369	  }
   370	
   371	  // On a resting piece, soft drop acts like a sideways move: it restarts the
   372	  // lock delay and never counts toward locking. It scores nothing there,
   373	  // because the piece does not move.
   374	  function softDrop() {
   375	    if (status !== "running" || !current) return;
   376	    if (!fits(current, 1, 0)) {
   377	      restartLockDelay();
   378	      return;
   379	    }
   380	    if (gravityStep()) score += SOFT_DROP_POINTS;
   381	  }
   382	
   383	  function move(dCol) {
   384	    if (status !== "running" || !current) return;
   385	    if (!fits(current, 0, dCol)) return;
   386	    var resting = !fits(current, 1, 0);
   387	    current.col += dCol;
   388	    if (resting) restartLockDelay();
   389	  }
   390	
   391	  function rotatedShape(p) {
   392	    var rot = (p.rot + 1) % 4;
   393	    if (p.type === "I") return { rot: rot, shape: I_STATES[rot] };
   394	    var size = p.type === "O" ? 2 : 3;
   395	    return {
   396	      rot: rot,
   397	      shape: p.shape.map(function (off) { return [off[1], size - 1 - off[0]]; })
   398	    };
   399	  }
   400	
   401	  // Rotate clockwise. If the turned shape does not fit, try shifting it
   402	  // sideways; if nothing fits, leave the piece exactly as it was.
   403	  function rotateCW() {
   404	    if (status !== "running" || !current) return;
   405	    var next = rotatedShape(current);
   406	    var trial = { row: current.row, col: current.col, shape: next.shape };
   407	    for (var i = 0; i < KICKS.length; i++) {
   408	      if (fits(trial, 0, KICKS[i])) {
   409	        current.col += KICKS[i];
   410	        current.rot = next.rot;
   411	        current.shape = next.shape;
   412	        return;
   413	      }
   414	    }
   415	  }
   416	
   417	  // Where the falling piece would land: its cells moved straight down as far
   418	  // as they fit.
   419	  function ghostCells() {
   420	    if (!current) return [];
   421	    var d = 0;
   422	    while (fits(current, d + 1, 0)) d++;
   423	    return pieceCells(current, d, 0);
   424	  }
   425	
   426	  function hardDrop() {
   427	    if (status !== "running" || !current) return;
   428	    while (fits(current, 1, 0)) {
   429	      current.row += 1;
   430	      score += HARD_DROP_POINTS;
   431	    }
   432	    lock();
   433	  }
   434	
   435	  // Set the falling piece aside. An empty slot takes it and the next piece
   436	  // comes in; a full slot swaps with it. One hold per piece until it locks.
   437	  function holdPiece() {
   438	    if (status !== "running" || !current || !canHold) return;
   439	    var type = current.type;
   440	    current = null;
   441	    canHold = false;
   442	    if (hold === null) {
   443	      hold = type;
   444	      spawn();
   445	    } else {
   446	      var out = hold;
   447	      hold = type;
   448	      enter(out);
   449	    }
   450	  }
   451	
   452	  var ACTIONS = {
   453	    left: function () { move(-1); },
   454	    right: function () { move(1); },
   455	    rotateCW: rotateCW,
   456	    softDrop: softDrop,
   457	    hardDrop: hardDrop,
   458	    hold: holdPiece,
   459	    pause: togglePause
   460	  };
   461	
   462	  // Pause freezes the game exactly as it is. The falling piece keeps its lock
   463	  // delay and lock resets, and resuming does not count as player input. The
   464	  // gravity timer also keeps its place: the next step comes after whatever
   465	  // time was left when the game paused, so pausing and resuming over and over
   466	  // cannot hold off a step and keep a resting piece from locking.
   467	  function togglePause() {
   468	    if (status === "running") {
   469	      pausedRemaining = Math.max(0, tickDue - Date.now());
   470	      stopTimer();
   471	      status = "paused";
   472	    } else if (status === "paused") {
   473	      status = "running";
   474	      // setLevel may have made steps faster during the pause.
   475	      schedule(Math.min(pausedRemaining, gravityInterval()));
   476	    }
   477	  }
   478	
   479	  // ---- Timer ----
   480	  function gravityInterval() {
   481	    return Math.max(100, 1000 - (level - 1) * 100);
   482	  }
   483	
   484	  function onTimer() {
   485	    timer = null;
   486	    startTimer();
   487	    gravityStep();
   488	    render();
   489	  }
   490	
   491	  function schedule(delay) {
   492	    stopTimer();
   493	    tickDue = Date.now() + delay;
   494	    timer = setTimeout(onTimer, delay);
   495	  }
   496	
   497	  function startTimer() {
   498	    schedule(gravityInterval());
   499	  }
   500	
   501	  function stopTimer() {
   502	    if (timer !== null) {
   503	      clearTimeout(timer);
   504	      timer = null;
   505	    }
   506	  }
   507	
   508	  // ---- Rendering (synchronous) ----
   509	  var boardEl = document.getElementById("board");
   510	  var overlayEl = document.getElementById("overlay");
   511	  var pausedEl = document.getElementById("paused");
   512	  var pauseBtnEl = document.getElementById("pause-btn");
   513	  var scoreEl = document.getElementById("score");
   514	  var levelEl = document.getElementById("level");
   515	  var linesEl = document.getElementById("lines");
   516	  var previewEl = document.getElementById("preview");
   517	  var holdEl = document.getElementById("hold");
   518	  var holdBoxEl = document.getElementById("hold-box");
   519	  var holdMinis = [];
   520	  var cellEls = [];
   521	  var previewItems = []; // [{ el, cells }] one per upcoming piece
   522	
   523	  (function buildDom() {
   524	    for (var r = 0; r < ROWS; r++) {
   525	      var row = [];
   526	      for (var c = 0; c < COLS; c++) {
   527	        var el = document.createElement("div");
   528	        el.className = "cell";
   529	        el.setAttribute("data-testid", "cell");
   530	        el.setAttribute("data-row", String(r));
   531	        el.setAttribute("data-col", String(c));
   532	        el.setAttribute("data-filled", "false");
   533	        el.setAttribute("data-piece", "");
   534	        el.setAttribute("data-ghost", "false");
   535	        boardEl.insertBefore(el, overlayEl);
   536	        row.push(el);
   537	      }
   538	      cellEls.push(row);
   539	    }
   540	    for (var i = 0; i < PREVIEW_COUNT; i++) {
   541	      var item = document.createElement("div");
   542	      item.className = "preview-item";
   543	      item.setAttribute("data-testid", "next-piece-item");
   544	      item.setAttribute("data-piece", "");
   545	      previewEl.appendChild(item);
   546	      previewItems.push({ el: item, cells: buildMinis(item) });
   547	    }
   548	    holdMinis = buildMinis(holdEl);
   549	  })();
   550	
   551	  function buildMinis(parent) {
   552	    var minis = [];
   553	    for (var k = 0; k < 8; k++) {
   554	      var m = document.createElement("div");
   555	      m.className = "mini";
   556	      parent.appendChild(m);
   557	      minis.push(m);
   558	    }
   559	    return minis;
   560	  }
   561	
   562	  function drawMini(minis, type) {
   563	    for (var k = 0; k < minis.length; k++) minis[k].className = "mini";
