  ok(await page.getByTestId('game-over').isVisible(), 'game over overlay');
  ok(await page.getByTestId('pause-btn').isDisabled(), 'pause disabled at game over');
  await page.keyboard.press('Enter'); s = await S(); eq(s.status, 'running', 'Enter restarts after game over');

  // ---- restart (new) ----
  async function dirty() {
    await T('newGame', ['T', 'O', 'I']);
    await T('setBoard', rows(['IIII......']));
    await T('input', 'hold');
    await T('input', 'softDrop');
    await T('setLevel', 5);
  }
  async function checkFresh(label) {
    const st = await S();
    eq([st.score, st.lines, st.level, st.status, st.hold], [0, 0, 1, 'running', null], label + ' state');
    ok((await T('getBoard')).every(r => r === E), label + ' empty board', await T('getBoard'));
    ok(st.current !== null, label + ' has a piece');
    eq(await page.getByTestId('score').textContent(), '0', label + ' score shown');
    eq(await page.getByTestId('lines').textContent(), '0', label + ' lines shown');
    eq(await page.getByTestId('level').textContent(), '1', label + ' level shown');
    ok(!(await page.getByTestId('game-over').isVisible()), label + ' no game over overlay');
    ok(!(await page.getByTestId('paused-indicator').isVisible()), label + ' no paused overlay');
    eq(await page.locator('[data-testid=cell][data-filled=true]').count(), 4, label + ' only falling piece drawn');
  }
  await dirty(); await page.getByTestId('restart-btn').click(); await checkFresh('btn running');
  await dirty(); await T('input', 'pause'); await page.getByTestId('restart-btn').click(); await checkFresh('btn paused');
  await T('newGame', ['O']); await T('setBoard', ['..........', '..........', 'OOOO.OOOO.'].concat(Array(17).fill('OOOO.OOOO.')));
  await T('setQueue', ['O']); await T('input', 'hardDrop'); eq((await S()).status, 'gameover', 'go');
  await page.getByTestId('restart-btn').click(); await checkFresh('btn gameover');
  await dirty(); await page.keyboard.press('r'); await checkFresh('r running');
  await dirty(); await T('input', 'pause'); await page.keyboard.press('R'); await checkFresh('R paused');
  await T('newGame', ['O']); await T('setBoard', ['..........', '..........', 'OOOO.OOOO.'].concat(Array(17).fill('OOOO.OOOO.')));
  await T('setQueue', ['O']); await T('input', 'hardDrop');
  await page.keyboard.press('r'); await checkFresh('r gameover');
  // restart button then Space should hard drop (focus dropped)
  await page.getByTestId('restart-btn').click();
  await page.keyboard.press('Space'); s = await S();
  ok(s.score > 0 && (await T('getBoard')).some(r => r !== E), 'Space after restart-btn hard drops', s.score);
  // gravity timer runs after restart
  await page.getByTestId('restart-btn').click();
  const r0 = (await S()).current.cells[0][0];
  await page.waitForTimeout(1150);
  ok((await S()).current.cells[0][0] > r0, 'gravity runs after restart');
  // Ctrl+R must not restart; key repeat must not hard drop twice
  await T('newGame', ['O', 'O', 'O']); await T('input', 'softDrop');
  await page.keyboard.down('Control'); await page.keyboard.press('r'); await page.keyboard.up('Control');
  eq((await S()).score, 1, 'Ctrl+R ignored');
  await T('newGame', ['O', 'O', 'O']);
  await page.evaluate(() => { document.dispatchEvent(new KeyboardEvent('keydown', { key: ' ', repeat: true, bubbles: true })); });
  eq((await S()).score, 0, 'repeated Space ignored');

  // ---- real-time pause keeps timer ----
  await T('newGame', ['O']);
  await page.waitForTimeout(600); await T('input', 'pause'); await page.waitForTimeout(1500);
  const pr = (await S()).current.cells[0][0]; eq(pr, 0, 'no fall while paused');
  await T('input', 'pause'); await page.waitForTimeout(550);
  eq((await S()).current.cells[0][0], 1, 'resume keeps remaining time');

  eq(errors, [], 'no console errors');
  console.log(`passes ${passes}, fails ${fails}`);
  await browser.close();
  process.exit(fails ? 1 : 0);
})();
EOF
